contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address log1, address log2) public payable {
        bool revertedInit;
        c.SetLogFile(log1); bool __rev0 = __ESBMC_reverted(); if (__rev0) { revertedInit = true; } else { revertedInit = false; }

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool revertedAfterInit;
        c.SetLogFile(log2); bool __rev1 = __ESBMC_reverted(); if (__rev1) { revertedAfterInit = true; } else { revertedAfterInit = false; }

        assert(!revertedInit && revertedAfterInit);
    }

    receive() external payable {}
}

